INSERT INTO categories (id, slug, position, status, image, title_en, title_fr, eyebrow_en, eyebrow_fr, summary_en, summary_fr, image_alt_en, image_alt_fr) VALUES (1, 'solid-tumor-biomarkers', 1, 'published', '/hero-diagnostics.png', 'Solid-Tumor Biomarkers', 'Biomarqueurs de tumeurs solides', 'Diagnostics', 'Diagnostic', 'A focused portfolio of biomarkers associated with solid-tumor detection and monitoring.', 'Un portefeuille ciblé de biomarqueurs associés à l’évaluation et au suivi des tumeurs solides.', 'Laboratory diagnostic equipment and sample droplet', 'Équipement de diagnostic en laboratoire et goutte d’échantillon');
INSERT INTO categories (id, slug, position, status, image, title_en, title_fr, eyebrow_en, eyebrow_fr, summary_en, summary_fr, image_alt_en, image_alt_fr) VALUES (2, 'targeted-therapeutics', 2, 'published', '/therapeutics-editorial.jpg', 'Targeted Therapeutics', 'Thérapies ciblées', 'Specialty medicines', 'Médicaments spécialisés', 'Specialized therapies presented for healthcare-professional and institutional audiences.', 'Des thérapies spécialisées destinées aux professionnels de la santé et aux établissements.', 'Healthcare professional preparing a vial in a clinical laboratory', 'Professionnel de la santé préparant un flacon en laboratoire clinique');
INSERT INTO categories (id, slug, position, status, image, title_en, title_fr, eyebrow_en, eyebrow_fr, summary_en, summary_fr, image_alt_en, image_alt_fr) VALUES (3, 'ophthalmology', 3, 'published', '/ophthalmology-editorial.jpg', 'Ophthalmology', 'Ophtalmologie', 'Eye health', 'Santé oculaire', 'A concise ophthalmology portfolio for the management of intraocular pressure.', 'Un portefeuille ophtalmologique concis pour la prise en charge de la pression intraoculaire.', 'Patient undergoing an ophthalmic examination', 'Patiente lors d’un examen ophtalmologique');
INSERT INTO categories (id, slug, position, status, image, title_en, title_fr, eyebrow_en, eyebrow_fr, summary_en, summary_fr, image_alt_en, image_alt_fr) VALUES (4, 'cardiology', 4, 'published', '/cardiology-signal.svg', 'Cardiology', 'Cardiologie', 'Cardiac diagnostics', 'Diagnostic cardiaque', 'Diagnostic tools and tests supporting timely cardiovascular assessment.', 'Des outils et tests diagnostiques pour soutenir l’évaluation cardiovasculaire.', 'Illustrated electrocardiogram signal', 'Illustration d’un signal électrocardiographique');
INSERT INTO categories (id, slug, position, status, image, title_en, title_fr, eyebrow_en, eyebrow_fr, summary_en, summary_fr, image_alt_en, image_alt_fr) VALUES (5, 'veterinary-diagnostics', 5, 'draft', '/hero-diagnostics.png', 'Veterinary Diagnostics', 'Diagnostics vétérinaires', 'Portfolio in development', 'Portefeuille en développement', 'A future diagnostic biomarker portfolio. Product information will be published after review.', 'Un futur portefeuille de biomarqueurs diagnostiques. Les renseignements seront publiés après révision.', 'Laboratory diagnostic equipment representing forthcoming veterinary testing', 'Équipement de laboratoire représentant les futurs diagnostics vétérinaires');
INSERT INTO categories (id, slug, position, status, image, title_en, title_fr, eyebrow_en, eyebrow_fr, summary_en, summary_fr, image_alt_en, image_alt_fr) VALUES (6, 'infant-formula-children-food', 6, 'draft', '/therapeutics-editorial.jpg', 'Infant Formulas & Children’s Food', 'Préparations pour nourrissons et aliments pour enfants', 'Portfolio in development', 'Portefeuille en développement', 'A future range of infant formulas and children’s food. Product information will be published after review.', 'Une future gamme de préparations pour nourrissons et d’aliments pour enfants. Les renseignements seront publiés après révision.', 'Healthcare professional in a clinical laboratory', 'Professionnel de la santé dans un laboratoire clinique');
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('afp', 1, 1, 1, 'https://ribicongroup.com/afp.html', '/products/alpha-fetoprotein-page-image.jpg', 325, 235, NULL, NULL, NULL, 'Alpha-fetoprotein (AFP)', 'Alpha-fœtoprotéine (AFP)', 'Solid-tumor biomarker', 'Biomarqueur de tumeur solide', 'A laboratory biomarker associated with assessment and monitoring in selected solid-tumor settings.', 'Un biomarqueur de laboratoire associé à l’évaluation et au suivi dans certains contextes de tumeurs solides.', 'The former site discusses AFP in relation to liver, ovarian, and testicular cancers, and notes that results are interpreted alongside other clinical information.', 'L’ancien site présente l’AFP dans le contexte des cancers du foie, de l’ovaire et du testicule, en précisant que le résultat doit être interprété avec les autres données cliniques.', 'Blood collection tube labelled AFP test on a tumor-marker request form', 'Tube de prélèvement sanguin portant l’étiquette AFP sur un formulaire de marqueurs tumoraux', NULL, NULL, '["A blood test that measures alpha-fetoprotein, a protein made by the liver.","Helps diagnose and monitor cancers of the liver, ovaries, or testicles that produce high AFP levels, when used with other exams and tests.","Used to follow how a cancer responds to treatment and to check whether it has returned.","Cannot screen for or diagnose cancer on its own: other conditions raise AFP, and some cancers leave it normal."]', '["Une analyse sanguine qui mesure l’alpha-fœtoprotéine, une protéine produite par le foie.","Aide à diagnostiquer et à suivre les cancers du foie, des ovaires ou des testicules qui produisent des taux élevés d’AFP, lorsqu’elle est utilisée avec d’autres examens et tests.","Sert à suivre la réponse d’un cancer au traitement et à vérifier s’il est réapparu.","Ne permet pas à elle seule de dépister ou de diagnostiquer un cancer : d’autres affections augmentent l’AFP, et certains cancers la laissent normale."]', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('ca-125', 1, 2, 1, 'https://ribicongroup.com/ca-125.html', '/products/ca-125-page-image.jpg', 325, 235, NULL, NULL, NULL, 'CA-125', 'CA-125', 'Solid-tumor biomarker', 'Biomarqueur de tumeur solide', 'A biomarker used in the clinical assessment and monitoring of ovarian cancer.', 'Un biomarqueur utilisé dans l’évaluation clinique et le suivi du cancer de l’ovaire.', 'The former site describes CA-125 in treatment response and recurrence monitoring; it is not presented as a stand-alone diagnosis.', 'L’ancien site décrit le CA-125 dans le suivi de la réponse au traitement et de la récidive; il ne constitue pas à lui seul un diagnostic.', 'Blood collection tube labelled CA 125 test on a tumor-marker request form', 'Tube de prélèvement sanguin portant l’étiquette CA 125 sur un formulaire de marqueurs tumoraux', NULL, NULL, '["A blood test that measures CA-125 (cancer antigen 125), a tumor marker often raised in ovarian cancer.","Most common use: checking whether ovarian-cancer treatment is working and whether the cancer has returned.","May be combined with imaging and other tests to assess a pelvic mass, or in people at very high risk of ovarian cancer.","Not a routine screening test: non-cancer conditions such as endometriosis or menstruation can also raise CA-125."]', '["Une analyse sanguine qui mesure le CA-125 (antigène cancéreux 125), un marqueur tumoral souvent élevé dans le cancer de l’ovaire.","Utilisation la plus courante : vérifier si le traitement du cancer de l’ovaire fonctionne et si le cancer est réapparu.","Peut être combiné à l’imagerie et à d’autres tests pour évaluer une masse pelvienne, ou chez les personnes à très haut risque de cancer de l’ovaire.","Ce n’est pas un test de dépistage de routine : des affections non cancéreuses, comme l’endométriose ou les menstruations, peuvent aussi élever le CA-125."]', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('gc-reaad', 1, 3, 1, 'https://ribicongroup.com/gastric-cancer.html', '/products/gastric-cancer-page-image.jpg', 300, 400, NULL, NULL, NULL, 'Gastric Carcinoma GC-REAAD', 'Carcinome gastrique GC-REAAD', 'Solid-tumor biomarker', 'Biomarqueur de tumeur solide', 'An investigational-style diagnostic offering associated with gastric carcinoma on the former site.', 'Une offre diagnostique associée au carcinome gastrique sur l’ancien site.', 'The legacy description identifies an ITIH3 ELISA assay for human plasma. Current availability, validation, and intended use require confirmation.', 'La description historique mentionne un dosage ELISA ITIH3 sur plasma humain. La disponibilité, la validation et l’usage prévu doivent être confirmés.', 'GC-REAAD ITIH3 highlights sheet showing sensitivity, specificity, and assay specifications', 'Fiche de caractéristiques GC-REAAD ITIH3 présentant la sensibilité, la spécificité et les spécifications du dosage', NULL, NULL, '["Restalyst GC-REAAD™ ITIH3 ELISA: an in-vitro diagnostic for the qualitative and semi-quantitative detection of ITIH3 protein in human plasma, intended for early detection of gastric carcinoma.","Built on a patented technology; ITIH3 is reported to be elevated in the plasma of gastric-carcinoma patients regardless of gastritis status or H. pylori infection.","Reports a positive or negative risk result using an arbitrary measurement scale called REAAD-units (RU)."]', '["Restalyst GC-REAAD™ ITIH3 ELISA : un diagnostic in vitro pour la détection qualitative et semi-quantitative de la protéine ITIH3 dans le plasma humain, destiné à la détection précoce du carcinome gastrique.","Repose sur une technologie brevetée; l’ITIH3 serait élevée dans le plasma des patients atteints d’un carcinome gastrique, indépendamment de la gastrite ou de l’infection à H. pylori.","Fournit un résultat de risque positif ou négatif à l’aide d’une échelle arbitraire appelée unités REAAD (RU)."]', 'A sandwich ELISA. Capture antibodies coated on the microwell bind ITIH3 in the plasma sample; detection antibodies and HRP-conjugated secondary antibodies are added, and a TMB substrate turns into a colour signal whose intensity is proportional to the antigen present. Wells are read on any suitable spectrophotometer or ELISA reader.', 'Un ELISA en sandwich. Des anticorps de capture fixés au fond des micropuits lient l’ITIH3 présente dans l’échantillon de plasma; des anticorps de détection et des anticorps secondaires conjugués à la HRP sont ajoutés, puis un substrat TMB produit un signal coloré dont l’intensité est proportionnelle à l’antigène présent. La lecture se fait sur tout spectrophotomètre ou lecteur ELISA approprié.', NULL, NULL, '[{"label":"Sensitivity","value":"91.0%"},{"label":"Specificity","value":"93.6%"},{"label":"Inter-assay precision","value":"7.59% – 8.64%"},{"label":"Intra-assay precision","value":"3.32% – 3.74%"},{"label":"Sample type","value":"Plasma"},{"label":"Assay duration (approx.)","value":"2 hours"},{"label":"Patient sample volume","value":"<10 µL"},{"label":"Shelf life","value":"12 months"},{"label":"Certification","value":"CE-IVD certified; HSA (Singapore) registered"}]', '[{"label":"Sensibilité","value":"91,0 %"},{"label":"Spécificité","value":"93,6 %"},{"label":"Précision inter-essai","value":"7,59 % – 8,64 %"},{"label":"Précision intra-essai","value":"3,32 % – 3,74 %"},{"label":"Type d’échantillon","value":"Plasma"},{"label":"Durée du dosage (approx.)","value":"2 heures"},{"label":"Volume d’échantillon du patient","value":"<10 µL"},{"label":"Durée de conservation","value":"12 mois"},{"label":"Certification","value":"Certifié CE-IVD; enregistré auprès de la HSA (Singapour)"}]');
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('hcc-reaad', 1, 4, 1, 'https://ribicongroup.com/hepatocellular-carcinoma.html', '/products/hepatocellular-page-image.jpg', 300, 400, NULL, NULL, NULL, 'Hepatocellular Carcinoma HCC-REAAD', 'Carcinome hépatocellulaire HCC-REAAD', 'Solid-tumor biomarker', 'Biomarqueur de tumeur solide', 'A diagnostic biomarker offering associated with hepatocellular carcinoma on the former site.', 'Une offre de biomarqueur diagnostique associée au carcinome hépatocellulaire.', 'The legacy description references an ERBB3 ELISA assay and an algorithm involving AFP. The precise intended use needs verification.', 'La description historique mentionne un dosage ELISA ERBB3 et un algorithme intégrant l’AFP. L’usage prévu précis doit être vérifié.', 'HCC-REAAD ERBB3 highlights sheet showing sensitivity, specificity, and assay specifications', 'Fiche de caractéristiques HCC-REAAD ERBB3 présentant la sensibilité, la spécificité et les spécifications du dosage', NULL, NULL, '["Restalyst HCC-REAAD™ ERBB3 ELISA: an in-vitro diagnostic for the qualitative and semi-quantitative detection of ERBB3 (HER-3) in human serum or plasma, intended for early detection of hepatocellular carcinoma.","ERBB3 (patented) is reported to be elevated in the serum or plasma of hepatocellular-carcinoma patients.","An algorithm (binary logistic regression) combining ERBB3 and AFP is presented as improving on routine screening with AFP alone."]', '["Restalyst HCC-REAAD™ ERBB3 ELISA : un diagnostic in vitro pour la détection qualitative et semi-quantitative de l’ERBB3 (HER-3) dans le sérum ou le plasma humain, destiné à la détection précoce du carcinome hépatocellulaire.","L’ERBB3 (brevetée) serait élevée dans le sérum ou le plasma des patients atteints d’un carcinome hépatocellulaire.","Un algorithme (régression logistique binaire) combinant l’ERBB3 et l’AFP est présenté comme une amélioration par rapport au dépistage de routine par l’AFP seule."]', 'A sandwich ELISA. Capture antibodies coated on the microwell bind ERBB3 in the sample; biotinylated detection antibodies and HRP-conjugated secondary antibodies are added, and a TMB substrate turns into a colour signal proportional to the antigen present. Wells are read on any suitable spectrophotometer or ELISA reader.', 'Un ELISA en sandwich. Des anticorps de capture fixés au fond des micropuits lient l’ERBB3 présente dans l’échantillon; des anticorps de détection biotinylés et des anticorps secondaires conjugués à la HRP sont ajoutés, puis un substrat TMB produit un signal coloré proportionnel à l’antigène présent. La lecture se fait sur tout spectrophotomètre ou lecteur ELISA approprié.', NULL, NULL, '[{"label":"Sensitivity","value":"91.1%"},{"label":"Specificity","value":"91.3%"},{"label":"Inter-assay precision","value":"2.16% – 2.87%"},{"label":"Intra-assay precision","value":"6.37% – 8.10%"},{"label":"Sample type","value":"Serum / plasma"},{"label":"Assay duration (approx.)","value":"2.0 hours"},{"label":"Patient sample volume","value":"<10 µL"},{"label":"Shelf life","value":"9 months"},{"label":"Certification","value":"CE-IVD certified; HSA (Singapore) registered"}]', '[{"label":"Sensibilité","value":"91,1 %"},{"label":"Spécificité","value":"91,3 %"},{"label":"Précision inter-essai","value":"2,16 % – 2,87 %"},{"label":"Précision intra-essai","value":"6,37 % – 8,10 %"},{"label":"Type d’échantillon","value":"Sérum / plasma"},{"label":"Durée du dosage (approx.)","value":"2,0 heures"},{"label":"Volume d’échantillon du patient","value":"<10 µL"},{"label":"Durée de conservation","value":"9 mois"},{"label":"Certification","value":"Certifié CE-IVD; enregistré auprès de la HSA (Singapour)"}]');
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('npc-reaad', 1, 5, 1, 'https://ribicongroup.com/nasopharyngeal-cancer.html', '/products/nasopharyngeal-page-image.jpg', 300, 400, NULL, NULL, NULL, 'Nasopharyngeal Carcinoma NPC-REAAD', 'Carcinome nasopharyngé NPC-REAAD', 'Solid-tumor biomarker', 'Biomarqueur de tumeur solide', 'A diagnostic biomarker offering associated with nasopharyngeal carcinoma on the former site.', 'Une offre de biomarqueur diagnostique associée au carcinome nasopharyngé.', 'The legacy description references an EBV EA-IgA ELISA assay using serum or plasma. Current specifications require confirmation.', 'La description historique mentionne un dosage ELISA EBV EA-IgA sur sérum ou plasma. Les spécifications actuelles doivent être confirmées.', 'NPC-REAAD highlights sheet showing sensitivity, specificity, and assay specifications', 'Fiche de caractéristiques NPC-REAAD présentant la sensibilité, la spécificité et les spécifications du dosage', NULL, NULL, '["Restalyst NPC-REAAD EBV EA-IgA ELISA: an in-vitro diagnostic for the qualitative and semi-quantitative detection of IgA antibodies in human serum or plasma, to aid in the diagnosis of nasopharyngeal carcinoma.","Uses highly specific Epstein-Barr virus proteins, produced with recombinant DNA technology, to detect the patient’s Early Antigen (EA) IgA response.","Reports a positive or negative risk result using an arbitrary measurement scale called REAAD-units (RU)."]', '["Restalyst NPC-REAAD EBV EA-IgA ELISA : un diagnostic in vitro pour la détection qualitative et semi-quantitative des anticorps IgA dans le sérum ou le plasma humain, afin d’aider au diagnostic du carcinome nasopharyngé.","Utilise des protéines très spécifiques du virus d’Epstein-Barr, produites par la technologie de l’ADN recombinant, pour détecter la réponse IgA contre l’antigène précoce (EA) du patient.","Fournit un résultat de risque positif ou négatif à l’aide d’une échelle arbitraire appelée unités REAAD (RU)."]', 'Recombinant NPC antigens are coated on the microwells. Human IgA against EBV EA proteins binds the antigens; after washing, HRP-conjugated secondary antibodies bind the complexes and a TMB substrate turns into a colour signal proportional to the amount present. Wells are read on any suitable spectrophotometer or ELISA reader.', 'Des antigènes NPC recombinants sont fixés au fond des micropuits. Les IgA humaines dirigées contre les protéines EA de l’EBV se lient aux antigènes; après lavage, des anticorps secondaires conjugués à la HRP se fixent aux complexes et un substrat TMB produit un signal coloré proportionnel à la quantité présente. La lecture se fait sur tout spectrophotomètre ou lecteur ELISA approprié.', 'The source graphic renders sensitivity and specificity as “960%” and “940%”; they are shown here as 96.0% and 94.0% and must be confirmed.', 'Le graphique d’origine affiche la sensibilité et la spécificité sous la forme « 960 % » et « 940 % »; elles sont présentées ici comme 96,0 % et 94,0 % et doivent être confirmées.', '[{"label":"Sensitivity","value":"96.0%"},{"label":"Specificity","value":"94.0%"},{"label":"Inter-assay precision","value":"2.99% – 3.65%"},{"label":"Intra-assay precision","value":"3.15% – 3.17%"},{"label":"Sample type","value":"Serum / plasma"},{"label":"Assay duration (approx.)","value":"1.5 hours"},{"label":"Patient sample volume","value":"<10 µL"},{"label":"Shelf life","value":"13 months"},{"label":"Certification","value":"CE-IVD certified; HSA (Singapore) and MDA (Malaysia) registered"}]', '[{"label":"Sensibilité","value":"96,0 %"},{"label":"Spécificité","value":"94,0 %"},{"label":"Précision inter-essai","value":"2,99 % – 3,65 %"},{"label":"Précision intra-essai","value":"3,15 % – 3,17 %"},{"label":"Type d’échantillon","value":"Sérum / plasma"},{"label":"Durée du dosage (approx.)","value":"1,5 heure"},{"label":"Volume d’échantillon du patient","value":"<10 µL"},{"label":"Durée de conservation","value":"13 mois"},{"label":"Certification","value":"Certifié CE-IVD; enregistré auprès de la HSA (Singapour) et de la MDA (Malaisie)"}]');
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('tepadina', 2, 6, 1, 'https://ribicongroup.com/tepadina.html', '/products/tepadina-page-image.jpg', 325, 350, NULL, NULL, NULL, 'Tepadina (thiotepa)', 'Tepadina (thiotépa)', 'Specialty therapeutic', 'Thérapie spécialisée', 'A thiotepa-based specialty medicine listed in Ribicon’s former therapeutic portfolio.', 'Un médicament spécialisé à base de thiotépa figurant dans l’ancien portefeuille thérapeutique de Ribicon.', 'The former site discusses use in conditioning before stem-cell transplantation and in selected oncology settings. Local authorization and approved indications must be checked before publication.', 'L’ancien site évoque son utilisation dans le conditionnement avant une greffe de cellules souches et dans certains contextes oncologiques. L’autorisation locale et les indications approuvées doivent être vérifiées.', 'Tepadina brand image with molecular illustration', 'Image de marque Tepadina avec illustration moléculaire', NULL, NULL, '["Active substance: thiotepa, supplied as a powder made up into a solution for infusion (drip into a vein).","Used in combination with other chemotherapy medicines.","As a conditioning (preparative) treatment before hematopoietic progenitor cell transplantation in patients with blood diseases, including leukemia, or diseases causing low red blood cell counts such as thalassemia or sickle-cell anaemia.","During treatment of solid tumors when high-dose chemotherapy followed by hematopoietic progenitor cell transplantation is needed."]', '["Substance active : le thiotépa, fourni sous forme de poudre pour solution pour perfusion (goutte-à-goutte dans une veine).","Utilisé en association avec d’autres médicaments de chimiothérapie.","Comme traitement de conditionnement (préparatoire) avant une greffe de cellules progénitrices hématopoïétiques chez des patients atteints de maladies du sang, dont la leucémie, ou de maladies entraînant une faible numération des globules rouges, comme la thalassémie ou la drépanocytose.","Lors du traitement de tumeurs solides lorsqu’une chimiothérapie à haute dose suivie d’une greffe de cellules progénitrices hématopoïétiques est nécessaire."]', NULL, NULL, NULL, NULL, '[{"label":"Strengths listed","value":"15 mg, 100 mg, 200 mg, 400 mg"}]', '[{"label":"Concentrations indiquées","value":"15 mg, 100 mg, 200 mg, 400 mg"}]');
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('phelinun', 2, 7, 1, 'https://ribicongroup.com/phelinun.html', '/products/phelinun-page-image.jpg', 325, 350, NULL, NULL, NULL, 'Phelinun (melphalan)', 'Phelinun (melphalan)', 'Specialty therapeutic', 'Thérapie spécialisée', 'A melphalan-based specialty medicine listed in Ribicon’s former therapeutic portfolio.', 'Un médicament spécialisé à base de melphalan figurant dans l’ancien portefeuille thérapeutique.', 'The former site describes oncology and transplantation-related uses. Current Canadian availability, labeling, and indications require confirmation.', 'L’ancien site décrit des utilisations en oncologie et en transplantation. La disponibilité, l’étiquetage et les indications au Canada doivent être confirmés.', 'Phelinun brand image with molecular illustration', 'Image de marque Phelinun avec illustration moléculaire', NULL, NULL, '["A cancer medicine used on its own or with other cancer medicines, radiotherapy, or both.","Listed uses: multiple myeloma, acute lymphoblastic leukemia and acute myeloid leukemia; Hodgkin and non-Hodgkin lymphomas; childhood neuroblastoma; ovarian cancer; and mammary adenocarcinoma, a type of breast cancer.","Also used with other cytotoxic medicines as conditioning treatment before stem-cell transplantation in adults and children with blood cancers and some other blood disorders in children."]', '["Un médicament contre le cancer utilisé seul ou avec d’autres médicaments anticancéreux, la radiothérapie, ou les deux.","Utilisations indiquées : myélome multiple, leucémie lymphoblastique aiguë et leucémie myéloïde aiguë; lymphomes hodgkiniens et non hodgkiniens; neuroblastome de l’enfant; cancer de l’ovaire; et adénocarcinome mammaire, un type de cancer du sein.","Également utilisé avec d’autres médicaments cytotoxiques comme traitement de conditionnement avant une greffe de cellules souches chez les adultes et les enfants atteints de cancers du sang et de certains autres troubles sanguins chez l’enfant."]', NULL, NULL, NULL, NULL, '[{"label":"Strengths listed","value":"50 mg, 200 mg"}]', '[{"label":"Concentrations indiquées","value":"50 mg, 200 mg"}]');
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('bimatoprost', 3, 8, 1, 'https://ribicongroup.com/bimatoprost.html', '/products/bimatoprost-page-image.jpg', 325, 235, NULL, NULL, NULL, 'Bimatoprost eye drops', 'Gouttes ophtalmiques de bimatoprost', 'Ophthalmology', 'Ophtalmologie', 'Prostaglandin-analogue eye drops included in the former ophthalmology portfolio.', 'Des gouttes ophtalmiques analogues des prostaglandines incluses dans l’ancien portefeuille.', 'The former site presents bimatoprost in the management of elevated intraocular pressure and glaucoma. Product-specific formulation and authorization need confirmation.', 'L’ancien site présente le bimatoprost pour la prise en charge de la pression intraoculaire élevée et du glaucome. La formulation et l’autorisation du produit doivent être confirmées.', 'Close-up of an eye examination with a slit lamp', 'Gros plan d’un examen de l’œil à la lampe à fente', NULL, NULL, '["A prostaglandin analogue for the treatment of glaucoma, a group of eye conditions that damage the optic nerve and are often associated with elevated intraocular pressure (IOP).","Primary open-angle glaucoma is the most common type (85–90% of cases): a slow, painless drainage blockage with no symptoms until late stages.","Treatment aims to lower IOP to a target level to halt optic-nerve damage. There is no cure, and vision lost to glaucoma is permanent."]', '["Un analogue des prostaglandines pour le traitement du glaucome, un groupe d’affections oculaires qui endommagent le nerf optique et sont souvent associées à une pression intraoculaire (PIO) élevée.","Le glaucome primitif à angle ouvert est le type le plus courant (85 à 90 % des cas) : une obstruction lente et indolore du drainage, sans symptômes avant les stades avancés.","Le traitement vise à abaisser la PIO à une valeur cible pour freiner l’atteinte du nerf optique. Il n’existe aucun remède, et la perte de vision causée par le glaucome est permanente."]', NULL, NULL, 'Figures are as presented on the former site and are not approved product claims.', 'Les chiffres sont ceux présentés sur l’ancien site et ne constituent pas des allégations de produit approuvées.', '[{"label":"Drug class","value":"Prostaglandin analogue"},{"label":"Mechanism","value":"Increases uveoscleral outflow"},{"label":"IOP reduction (legacy figure)","value":"25–35%"},{"label":"Dosing (legacy)","value":"Once daily, in the evening"}]', '[{"label":"Classe de médicament","value":"Analogue des prostaglandines"},{"label":"Mécanisme","value":"Augmente l’écoulement uvéo-scléral"},{"label":"Réduction de la PIO (chiffre historique)","value":"25 à 35 %"},{"label":"Posologie (historique)","value":"Une fois par jour, le soir"}]');
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('latanoprost', 3, 9, 1, 'https://ribicongroup.com/latanoprost.html', '/products/latanoprost-page-image.jpg', 325, 235, NULL, NULL, NULL, 'Latanoprost eye drops', 'Gouttes ophtalmiques de latanoprost', 'Ophthalmology', 'Ophtalmologie', 'Prostaglandin-analogue eye drops included in the former ophthalmology portfolio.', 'Des gouttes ophtalmiques analogues des prostaglandines incluses dans l’ancien portefeuille.', 'The former site presents latanoprost in the management of elevated intraocular pressure and glaucoma. Product-specific formulation and authorization need confirmation.', 'L’ancien site présente le latanoprost pour la prise en charge de la pression intraoculaire élevée et du glaucome. La formulation et l’autorisation du produit doivent être confirmées.', 'Close-up of an eye examination with a slit lamp', 'Gros plan d’un examen de l’œil à la lampe à fente', NULL, NULL, '["A prostaglandin analogue for the treatment of glaucoma, a group of eye conditions that damage the optic nerve and are often associated with elevated intraocular pressure (IOP).","Primary open-angle glaucoma is the most common type (85–90% of cases): a slow, painless drainage blockage with no symptoms until late stages.","Treatment aims to lower IOP to a target level to halt optic-nerve damage. There is no cure, and vision lost to glaucoma is permanent."]', '["Un analogue des prostaglandines pour le traitement du glaucome, un groupe d’affections oculaires qui endommagent le nerf optique et sont souvent associées à une pression intraoculaire (PIO) élevée.","Le glaucome primitif à angle ouvert est le type le plus courant (85 à 90 % des cas) : une obstruction lente et indolore du drainage, sans symptômes avant les stades avancés.","Le traitement vise à abaisser la PIO à une valeur cible pour freiner l’atteinte du nerf optique. Il n’existe aucun remède, et la perte de vision causée par le glaucome est permanente."]', NULL, NULL, 'Figures are as presented on the former site and are not approved product claims.', 'Les chiffres sont ceux présentés sur l’ancien site et ne constituent pas des allégations de produit approuvées.', '[{"label":"Drug class","value":"Prostaglandin analogue"},{"label":"Mechanism","value":"Increases uveoscleral outflow"},{"label":"IOP reduction (legacy figure)","value":"25–35%"},{"label":"Dosing (legacy)","value":"Once daily, in the evening"}]', '[{"label":"Classe de médicament","value":"Analogue des prostaglandines"},{"label":"Mécanisme","value":"Augmente l’écoulement uvéo-scléral"},{"label":"Réduction de la PIO (chiffre historique)","value":"25 à 35 %"},{"label":"Posologie (historique)","value":"Une fois par jour, le soir"}]');
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('vectraplex', 4, 10, 1, 'https://ribicongroup.com/vectraplex.html', '/products/vectraplex-page-image.jpg', 325, 350, '/products/vectraplex-page-image02.png', 817, 341, 'Vectraplex ECG', 'ECG Vectraplex', 'Cardiology / medical device', 'Cardiologie / dispositif médical', 'An electrocardiography system retained from the former cardiology and medical-device listings.', 'Un système d’électrocardiographie conservé de l’ancien portefeuille de cardiologie et de dispositifs médicaux.', 'The former site describes a five-electrode configuration that derives multi-lead ECG information. Technical performance and device authorization require review.', 'L’ancien site décrit une configuration à cinq électrodes produisant des données ECG multicanaux. Les performances techniques et l’autorisation du dispositif doivent être révisées.', 'Clinician placing ECG electrodes on a patient while viewing the trace on a tablet', 'Clinicienne plaçant des électrodes ECG sur un patient tout en consultant le tracé sur une tablette', 'Diagram comparing current 12-lead electrode placement with the five-electrode Vectraplex ECG placement', 'Schéma comparant le placement actuel des électrodes pour l’ECG à 12 dérivations et le placement à cinq électrodes de Vectraplex ECG', '["A Cardiac Electrical Biomarker (CEB): a continuous biomarker for detecting ECG changes suggestive of acute myocardial infarction (AMI), with the former site asking “Can you detect an AMI in real-time?”.","Non-invasive: derives a 22-lead ECG (EU) or 15-lead ECG (US) from only five electrodes.","22-lead = 12-lead, right-heart, posterior, and vectorcardiogram (XYZ) leads with vector loops. 15-lead = 12-lead plus vectorcardiogram leads and vector loops.","Also produces a standard 12-lead ECG with 10 electrodes, and may reduce electrode-placement error."]', '["Un biomarqueur électrique cardiaque (CEB) : un biomarqueur continu pour détecter les changements à l’ECG évocateurs d’un infarctus aigu du myocarde (IAM). L’ancien site demandait : « Pouvez-vous détecter un IAM en temps réel? ».","Non invasif : dérive un ECG à 22 dérivations (UE) ou à 15 dérivations (É.-U.) à partir de seulement cinq électrodes.","22 dérivations = 12 dérivations, cœur droit, dérivations postérieures et dérivations vectocardiographiques (XYZ) avec boucles vectorielles. 15 dérivations = 12 dérivations plus dérivations vectocardiographiques et boucles vectorielles.","Produit aussi un ECG standard à 12 dérivations avec 10 électrodes et pourrait réduire les erreurs de placement des électrodes."]', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO products (slug, category_id, position, published, legacy_url, image, image_width, image_height, second_image, second_image_width, second_image_height, name_en, name_fr, category_label_en, category_label_fr, overview_en, overview_fr, legacy_context_en, legacy_context_fr, image_alt_en, image_alt_fr, second_image_alt_en, second_image_alt_fr, highlights_en, highlights_fr, how_it_works_en, how_it_works_fr, specs_note_en, specs_note_fr, specs_en, specs_fr) VALUES ('troponin', 4, 11, 1, 'https://ribicongroup.com/troponin.html', '/products/troponin-page-image.jpg', 325, 219, NULL, NULL, NULL, 'Troponin test', 'Test de troponine', 'Cardiology biomarker', 'Biomarqueur cardiaque', 'A cardiac biomarker test included in the former Ribicon portfolio.', 'Un test de biomarqueur cardiaque inclus dans l’ancien portefeuille de Ribicon.', 'The former site discusses troponin as a marker used in evaluating heart-muscle injury. The exact assay and product details remain to be confirmed.', 'L’ancien site présente la troponine comme marqueur utilisé dans l’évaluation d’une atteinte du muscle cardiaque. Le dosage et le produit exacts restent à confirmer.', 'Blood collection tube labelled Troponin-T test on a cardiology request form', 'Tube de prélèvement sanguin portant l’étiquette Troponine-T sur un formulaire de cardiologie', NULL, NULL, '["Measures cardiac troponin (troponin I or T), a protein in heart muscle that is released into the blood when the heart muscle is damaged; more damage releases more troponin.","Most often used to help diagnose a heart attack, and sometimes to monitor angina.","Usually repeated two or more times over 24 hours to see how levels change.","A standard blood draw; no special preparation is needed."]', '["Mesure la troponine cardiaque (troponine I ou T), une protéine du muscle cardiaque libérée dans le sang lorsque le muscle cardiaque est endommagé; plus l’atteinte est importante, plus la troponine libérée est abondante.","Le plus souvent utilisée pour aider à diagnostiquer une crise cardiaque, et parfois pour suivre l’angine de poitrine.","Habituellement répétée au moins deux fois sur 24 heures pour observer l’évolution des taux.","Une prise de sang standard; aucune préparation particulière n’est nécessaire."]', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO hero_slides (position, active, image, image_alt_en, image_alt_fr, eyebrow_en, eyebrow_fr, title_en, title_fr, body_en, body_fr) VALUES (1, 1, '/hero-diagnostics.png', 'Precision laboratory diagnostic equipment with a suspended sample droplet', 'Équipement de diagnostic de précision avec une goutte d’échantillon', 'Canada-based specialty healthcare', 'Soins spécialisés basés au Canada', 'Precision in every possibility.', 'La précision ouvre les possibles.', 'Ribicon Pharma connects specialized diagnostics and therapies with the healthcare professionals and partners who move patient care forward.', 'Ribicon Pharma relie diagnostics et thérapies spécialisés aux professionnels et partenaires qui font progresser les soins.');
INSERT INTO hero_slides (position, active, image, image_alt_en, image_alt_fr, eyebrow_en, eyebrow_fr, title_en, title_fr, body_en, body_fr) VALUES (2, 1, '/ophthalmology-editorial.jpg', 'Ophthalmic examination in a clinical setting', 'Examen ophtalmologique en milieu clinique', 'Ophthalmology', 'Ophtalmologie', 'Clarity for specialized eye care.', 'La clarté au service des soins oculaires.', 'Trusted ophthalmic treatments, supplied to the clinicians and partners who protect vision.', 'Des traitements ophtalmiques de confiance, destinés aux cliniciens et partenaires qui protègent la vision.');
INSERT INTO hero_slides (position, active, image, image_alt_en, image_alt_fr, eyebrow_en, eyebrow_fr, title_en, title_fr, body_en, body_fr) VALUES (3, 1, '/therapeutics-editorial.jpg', 'Specialty therapeutics in a clinical setting', 'Thérapies spécialisées en milieu clinique', 'Specialty therapeutics', 'Thérapies spécialisées', 'Specialty medicines, delivered with care.', 'Des médicaments spécialisés, livrés avec soin.', 'A focused range of therapies, backed by commercial discipline and long-term partnerships.', 'Une gamme ciblée de thérapies, soutenue par la rigueur commerciale et des partenariats durables.');
